// CSD_RATIONALE_BEGIN
// Root cause: best result (49.7%) uses exact token equality `next == "<<"` which
// fails when the tokenizer emits " <<" or splits "<<" across tokens. All 300
// examples show "visible << : 0/300" yet spans ARE being extracted (hidden path).
// The primary failure mode is semantic mismatch (146/300 syntax-valid but wrong
// SQL), caused by the model hallucinating table/column names not in the schema.
//
// This attempt makes targeted fixes over the 49.7% best:
// 1. Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` to correctly
//    detect delimiter entry regardless of whitespace-prefixed or split tokens.
// 2. Strengthen task guidance to emphasize using ONLY exact schema names, which
//    pushes the model toward grounded identifier selection.
// 3. Keep 5-step preamble, GroupBoostedConstrainedStep(6.0), and the
//    CloseSpanWithinBudget(≤80) fallback that produced the best results.
// 4. The preamble `steps < 5` guard prevents wasting budget on "SQL: " prefix.
// 5. IsCompletePrefix is used for early close (not removed – removing it hurt in
//    attempt 40; adding a min-length guard also hurt in attempt 42).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so insideConstrainedOut
//   can only flip true when RenderedEndsWith fires. We set currentConstrainedOut := []
//   which satisfies IsValidPrefix([]) by method precondition. On EOS break,
//   insideConstrainedOut stays false, making the implication vacuous.
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut. Helper sets
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 main loop:
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making implication vacuously true, and clears currentConstrainedOut := [].
//   Normal step branch: GroupBoostedConstrainedStep hard-masks to parser-valid tokens
//   plus EOS. AppendConstrainedToken extends currentConstrainedOut by one valid token,
//   preserving IsValidPrefix by the parser extension contract.
//   EOS branch: close is only called when IsCompletePrefix holds, and CloseConstrainedSpan
//   sets insideConstrainedOut := false.
//
// Phase 4: CloseSpanWithinBudget postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 on non-EOS). Invariant is preserved each iteration.
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   |generated| grows by 1, steps grows by 1, invariant preserved.
// Phase 3: IsCompletePrefix branch: steps += 1, CloseConstrainedSpan appends at most
//   1 ">>" token; net ≤ 1 token per +1 step. Normal branch: steps += 1
//   (GroupBoostedConstrainedStep), AppendConstrainedToken appends 1 token; net 1:1.
//   EOS+close path: steps += 1 (EOS) then +1 (close), generated grows by at most 1.
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| + budget,
//   and steps := steps_before + closeBudget where closeBudget = min(remaining, 80);
//   |generated| <= |generatedPrefix| + steps is maintained.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with schema-token boosting
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

